#!/usr/bin/env python3
"""
checkability.py — score and report Halcyon Threshold checkability assessments.

Standard library only. Python 3.9+.

Usage:
    python tools/checkability.py validate [--dir data/assessments]
    python tools/checkability.py report   [--dir data/assessments] [--out report.md]
    python tools/checkability.py agreement [--dir data/assessments]
    python tools/checkability.py selftest

Design notes:
  * An item score with no supporting evidence note is rejected. This is deliberate: the rubric is
    only as good as the evidence trail, and it is easy to drift into scoring from memory.
  * "NA" is permitted only on items where the rubric allows it, and NA items are dropped from both
    the numerator and the denominator so that scores stay comparable.
  * Nothing here decides anything. It arithmetic-checks human judgement and makes disagreement
    visible.
"""

from __future__ import annotations

import argparse
import json
import pathlib
import sys
from collections import defaultdict
from typing import Any, Dict, List, Optional, Tuple

RUBRIC_VERSION = "0.1"
MIN_NOTE_CHARS = 15

# key, human label, is "NA" an allowed score?
ITEMS: List[Tuple[str, str, bool]] = [
    ("claim_specificity", "Claim specificity", False),
    ("model_identification", "Model identification", False),
    ("artifact_availability", "Artifact availability", False),
    ("data_and_contamination", "Data availability and contamination", False),
    ("scaffold_disclosure", "Scaffold and tool disclosure", True),
    ("grader_disclosure", "Grader disclosure", True),
    ("determinism_variance", "Determinism and variance", False),
    ("replication_cost", "Replication cost", False),
    ("negative_results", "Negative results and ablations", False),
    ("prior_checking", "Prior independent checking", False),
]

ITEM_KEYS = [k for k, _, _ in ITEMS]
ITEM_LABELS = {k: label for k, label, _ in ITEMS}
NA_ALLOWED = {k: na for k, _, na in ITEMS}

VALID_SCORES = {0, 1, 2}


class ValidationError(Exception):
    pass


# ----------------------------------------------------------------------------- loading


def load_dir(directory: pathlib.Path) -> List[Dict[str, Any]]:
    """Load every *.json assessment in a directory, skipping templates."""
    records = []
    for path in sorted(directory.glob("*.json")):
        if path.name.startswith("_") or "TEMPLATE" in path.name.upper():
            continue
        with path.open("r", encoding="utf-8") as fh:
            try:
                data = json.load(fh)
            except json.JSONDecodeError as exc:
                raise ValidationError(f"{path.name}: not valid JSON — {exc}") from exc
        data["_file"] = path.name
        records.append(data)
    return records


# -------------------------------------------------------------------------- validation


def validate(record: Dict[str, Any]) -> List[str]:
    """Return a list of problems. Empty list means the record is usable."""
    problems: List[str] = []
    where = record.get("_file", "<record>")

    for field in ("paper", "coder", "coded_on", "rubric_version", "items"):
        if field not in record:
            problems.append(f"{where}: missing top-level field '{field}'")

    paper = record.get("paper", {})
    if not isinstance(paper, dict):
        problems.append(f"{where}: 'paper' must be an object")
    else:
        for field in ("id", "title"):
            if not paper.get(field):
                problems.append(f"{where}: paper.{field} is missing or empty")

    if record.get("rubric_version") != RUBRIC_VERSION:
        problems.append(
            f"{where}: rubric_version {record.get('rubric_version')!r} "
            f"does not match tool version {RUBRIC_VERSION!r}"
        )

    items = record.get("items", {})
    if not isinstance(items, dict):
        problems.append(f"{where}: 'items' must be an object")
        return problems

    for key in ITEM_KEYS:
        if key not in items:
            problems.append(f"{where}: missing rubric item '{key}'")
            continue
        entry = items[key]
        if not isinstance(entry, dict):
            problems.append(f"{where}: item '{key}' must be an object with score and note")
            continue

        score = entry.get("score")
        if score == "NA":
            if not NA_ALLOWED[key]:
                problems.append(f"{where}: item '{key}' may not be scored NA")
        elif score not in VALID_SCORES:
            problems.append(f"{where}: item '{key}' has invalid score {score!r} (expected 0, 1, 2 or 'NA')")

        note = (entry.get("note") or "").strip()
        if len(note) < MIN_NOTE_CHARS:
            problems.append(
                f"{where}: item '{key}' needs an evidence note of at least "
                f"{MIN_NOTE_CHARS} characters (got {len(note)})"
            )

    for key in items:
        if key not in ITEM_KEYS:
            problems.append(f"{where}: unknown rubric item '{key}'")

    return problems


# ------------------------------------------------------------------------------ scoring


def score_record(record: Dict[str, Any]) -> Dict[str, Any]:
    items = record.get("items", {})
    earned = 0
    possible = 0
    na_items: List[str] = []

    for key in ITEM_KEYS:
        score = items.get(key, {}).get("score")
        if score == "NA":
            na_items.append(key)
            continue
        if score in VALID_SCORES:
            earned += score
            possible += 2

    pct = (100.0 * earned / possible) if possible else 0.0
    return {
        "paper_id": record.get("paper", {}).get("id", "?"),
        "title": record.get("paper", {}).get("title", "?"),
        "coder": record.get("coder", "?"),
        "earned": earned,
        "possible": possible,
        "pct": pct,
        "na_items": na_items,
    }


def band(pct: float) -> str:
    """Coarse descriptive band. Deliberately coarse: the rubric is not precise enough for ranks."""
    if pct >= 75:
        return "checkable"
    if pct >= 45:
        return "partially checkable"
    return "not checkable as published"


# ---------------------------------------------------------------------------- agreement


def agreement(records: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Exact per-item agreement across papers coded by two or more coders."""
    by_paper: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
    for rec in records:
        by_paper[rec.get("paper", {}).get("id", "?")].append(rec)

    double_coded = {pid: recs for pid, recs in by_paper.items() if len(recs) >= 2}

    per_item_agree: Dict[str, int] = defaultdict(int)
    per_item_total: Dict[str, int] = defaultdict(int)
    disagreements: List[Dict[str, Any]] = []

    for pid, recs in sorted(double_coded.items()):
        a, b = recs[0], recs[1]  # first two codings; extras reported but not paired
        for key in ITEM_KEYS:
            sa = a.get("items", {}).get(key, {}).get("score")
            sb = b.get("items", {}).get(key, {}).get("score")
            per_item_total[key] += 1
            if sa == sb:
                per_item_agree[key] += 1
            else:
                disagreements.append(
                    {
                        "paper_id": pid,
                        "item": key,
                        "a_coder": a.get("coder"),
                        "a_score": sa,
                        "b_coder": b.get("coder"),
                        "b_score": sb,
                    }
                )

    total_pairs = sum(per_item_total.values())
    total_agree = sum(per_item_agree.values())

    return {
        "double_coded_papers": len(double_coded),
        "overall_agreement": (100.0 * total_agree / total_pairs) if total_pairs else None,
        "per_item": {
            key: (100.0 * per_item_agree[key] / per_item_total[key]) if per_item_total[key] else None
            for key in ITEM_KEYS
        },
        "disagreements": disagreements,
    }


# ------------------------------------------------------------------------------ reports


def build_report(records: List[Dict[str, Any]]) -> str:
    lines: List[str] = []
    lines.append("# Checkability assessment report")
    lines.append("")
    lines.append(f"Rubric version {RUBRIC_VERSION}. Assessments: {len(records)}.")
    lines.append("")
    lines.append(
        "> Checkability measures whether an independent party could verify the paper's central "
        "claim. It does **not** measure whether the claim is true, or whether the work is good. "
        "Low scores often have legitimate causes. See `projects/replication-notes/METHOD.md`."
    )
    lines.append("")

    if not records:
        lines.append("_No assessments recorded yet._")
        return "\n".join(lines)

    scored = [score_record(r) for r in records]

    lines.append("## Per-assessment")
    lines.append("")
    lines.append("| Paper | Coder | Score | % | Band |")
    lines.append("|---|---|---|---|---|")
    for s in sorted(scored, key=lambda x: (x["paper_id"], x["coder"])):
        lines.append(
            f"| {s['paper_id']} — {s['title']} | {s['coder']} | {s['earned']}/{s['possible']} "
            f"| {s['pct']:.0f}% | {band(s['pct'])} |"
        )
    lines.append("")

    lines.append("## Per-item averages across the sample")
    lines.append("")
    lines.append("| Item | Mean score (0–2) | n |")
    lines.append("|---|---|---|")
    for key in ITEM_KEYS:
        vals = [
            r["items"][key]["score"]
            for r in records
            if key in r.get("items", {}) and r["items"][key].get("score") in VALID_SCORES
        ]
        if vals:
            lines.append(f"| {ITEM_LABELS[key]} | {sum(vals) / len(vals):.2f} | {len(vals)} |")
        else:
            lines.append(f"| {ITEM_LABELS[key]} | — | 0 |")
    lines.append("")

    agr = agreement(records)
    lines.append("## Inter-rater agreement")
    lines.append("")
    if agr["double_coded_papers"] == 0:
        lines.append(
            "_No papers have been independently double-coded. Scores in this report are "
            "single-coder judgements and should not be presented as measurements._"
        )
    else:
        lines.append(
            f"Double-coded papers: {agr['double_coded_papers']}. "
            f"Overall exact agreement: {agr['overall_agreement']:.0f}%."
        )
        lines.append("")
        lines.append("| Item | Exact agreement |")
        lines.append("|---|---|")
        for key in ITEM_KEYS:
            v = agr["per_item"][key]
            lines.append(f"| {ITEM_LABELS[key]} | {'—' if v is None else f'{v:.0f}%'} |")
        if agr["disagreements"]:
            lines.append("")
            lines.append("### Unresolved disagreements")
            lines.append("")
            for d in agr["disagreements"]:
                lines.append(
                    f"- `{d['paper_id']}` / {ITEM_LABELS[d['item']]}: "
                    f"{d['a_coder']}={d['a_score']} vs {d['b_coder']}={d['b_score']}"
                )
    lines.append("")
    return "\n".join(lines)


# --------------------------------------------------------------------------------- cli


def cmd_validate(args) -> int:
    records = load_dir(pathlib.Path(args.dir))
    problems: List[str] = []
    for rec in records:
        problems.extend(validate(rec))
    if problems:
        print(f"{len(problems)} problem(s) found in {len(records)} record(s):\n")
        for p in problems:
            print("  - " + p)
        return 1
    print(f"OK — {len(records)} record(s) valid against rubric {RUBRIC_VERSION}.")
    return 0


def cmd_report(args) -> int:
    records = load_dir(pathlib.Path(args.dir))
    blocking = [p for rec in records for p in validate(rec)]
    if blocking:
        print("Refusing to report: records do not validate. Run `validate` first.", file=sys.stderr)
        return 1
    text = build_report(records)
    if args.out:
        pathlib.Path(args.out).write_text(text, encoding="utf-8")
        print(f"Wrote {args.out}")
    else:
        print(text)
    return 0


def cmd_agreement(args) -> int:
    records = load_dir(pathlib.Path(args.dir))
    agr = agreement(records)
    print(json.dumps({k: v for k, v in agr.items() if k != "disagreements"}, indent=2))
    for d in agr["disagreements"]:
        print(f"  disagree: {d['paper_id']} {d['item']} {d['a_score']} vs {d['b_score']}")
    return 0


def _fixture(paper_id: str, coder: str, scores: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "_file": f"{paper_id}-{coder}.json",
        "paper": {"id": paper_id, "title": "Fixture paper"},
        "coder": coder,
        "coded_on": "2026-11-16",
        "rubric_version": RUBRIC_VERSION,
        "items": {
            k: {"score": scores.get(k, 1), "note": "fixture evidence note, section 3, page 4"}
            for k in ITEM_KEYS
        },
    }


def cmd_selftest(_args) -> int:
    failures = []

    good = _fixture("FIX-001", "a", {})
    if validate(good):
        failures.append(f"valid fixture rejected: {validate(good)}")

    s = score_record(good)
    if (s["earned"], s["possible"]) != (10, 20):
        failures.append(f"scoring wrong: got {s['earned']}/{s['possible']}, expected 10/20")

    na = _fixture("FIX-002", "a", {"scaffold_disclosure": "NA"})
    if validate(na):
        failures.append(f"legal NA rejected: {validate(na)}")
    sna = score_record(na)
    if sna["possible"] != 18:
        failures.append(f"NA not excluded from denominator: possible={sna['possible']}, expected 18")

    bad_na = _fixture("FIX-003", "a", {"claim_specificity": "NA"})
    if not any("may not be scored NA" in p for p in validate(bad_na)):
        failures.append("illegal NA accepted")

    no_note = _fixture("FIX-004", "a", {})
    no_note["items"]["claim_specificity"]["note"] = "n/a"
    if not any("evidence note" in p for p in validate(no_note)):
        failures.append("missing evidence note accepted")

    out_of_range = _fixture("FIX-005", "a", {"replication_cost": 5})
    if not any("invalid score" in p for p in validate(out_of_range)):
        failures.append("out-of-range score accepted")

    pair = [
        _fixture("FIX-006", "morgan", {"model_identification": 0}),
        _fixture("FIX-006", "priya", {"model_identification": 2}),
    ]
    agr = agreement(pair)
    if agr["double_coded_papers"] != 1:
        failures.append("double-coded pair not detected")
    if abs(agr["overall_agreement"] - 90.0) > 0.01:
        failures.append(f"agreement miscomputed: {agr['overall_agreement']}, expected 90.0")
    if len(agr["disagreements"]) != 1:
        failures.append("disagreement not recorded")

    if "checkable" not in build_report([good]):
        failures.append("report did not render")

    if failures:
        print("SELFTEST FAILED")
        for f in failures:
            print("  - " + f)
        return 1
    print("SELFTEST PASSED — 8 checks")
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = parser.add_subparsers(dest="cmd", required=True)

    for name, fn in (("validate", cmd_validate), ("report", cmd_report), ("agreement", cmd_agreement)):
        p = sub.add_parser(name)
        p.add_argument("--dir", default="data/assessments")
        if name == "report":
            p.add_argument("--out", default=None)
        p.set_defaults(func=fn)

    p = sub.add_parser("selftest")
    p.set_defaults(func=cmd_selftest)

    args = parser.parse_args()
    try:
        return args.func(args)
    except ValidationError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
